with seed(module_slug,level,title,description,steps) as (values ('hygiene',1,'Preventing cross-contamination','Identify contamination routes and apply controls.','["Separate raw and ready-to-eat foods during storage and preparation.","Wash hands thoroughly after handling raw food and before handling ready-to-eat food.","Clean and disinfect equipment using the correct contact time and workplace procedure.","Record and report failures before serving affected food."]'::jsonb),
('knife-skills',1,'Precision vegetable cuts','Practise consistent cuts safely.','["Use a stable chopping board and suitable sharp knife.","Use a claw grip and keep fingertips clear of the blade.","Practise baton, dice and julienne on suitable vegetables.","Compare size and consistency and clean equipment safely."]'::jsonb),
('preparation',1,'Planning a preparation list','Organise a section before service.','["Read recipes and forecast portions.","List tasks in dependency order and identify allergens.","Gather equipment and label prepared ingredients using workplace procedures.","Check readiness with the section leader before service."]'::jsonb),
('cooking-methods',1,'Essential cooking methods','Compare moist and dry heat.','["Compare boiling, steaming, roasting and shallow frying.","Choose a method appropriate to texture and ingredient.","Use a clean calibrated probe and follow validated workplace cooking controls.","Evaluate texture, colour and flavour and record any corrective action."]'::jsonb),
('stocks-sauces',2,'Stocks and reduction sauces','Build flavour and consistency.','["Select suitable bones or vegetables and cold water for stock.","Simmer gently, skim and strain safely.","Reduce a portion and assess flavour before seasoning.","Cool and store according to the workplace food safety plan."]'::jsonb),
('protein',2,'Preparing and cooking proteins','Plan safe protein preparation.','["Identify the cut or species and suitable cooking method.","Keep raw proteins separate and use dedicated clean equipment.","Follow validated cooking requirements for the product and check with a clean probe.","Rest where appropriate, portion and assess yield."]'::jsonb),
('vegetables',2,'Vegetable cookery and texture','Select methods for seasonal produce.','["Inspect and wash produce appropriately.","Cut evenly for consistent cooking.","Compare steaming and roasting for flavour and texture.","Taste, season and assess waste and portion yield."]'::jsonb),
('pastry',2,'Shortcrust pastry fundamentals','Control dough temperature and handling.','["Weigh ingredients accurately and identify allergens.","Rub fat into flour and add sufficient liquid without overworking.","Rest and chill dough before rolling evenly.","Bake according to the recipe and assess shrinkage and texture."]'::jsonb),
('allergens',2,'Managing allergen orders','Communicate and control allergen risk.','["Use current ingredient specifications and the approved allergen matrix.","Confirm the request with the kitchen and never guess ingredients.","Prevent cross-contact with clean equipment and controlled preparation.","If safety cannot be assured, explain this to the customer through the responsible person."]'::jsonb),
('advanced-techniques',3,'Controlled cooking and finishing','Assess consistency across portions.','["Define target texture, portion size and service timing.","Use a validated cooking process appropriate to the food.","Compare trial portions for consistency and record results.","Adjust finishing and presentation without compromising food safety."]'::jsonb),
('menu-development',3,'Designing a balanced menu','Develop a practical menu concept.','["Define the customer, price point and kitchen capacity.","Balance flavours, textures, dietary needs and seasonal ingredients.","Test recipes and document allergens and portion sizes.","Review service feasibility and gather structured feedback."]'::jsonb),
('costing',3,'Recipe costing and yield','Calculate usable yield and portion cost.','["Record purchase weights and costs.","Measure trim and cooking losses to calculate usable yield.","Divide total recipe ingredient cost by saleable portions.","Compare actual costs with targets and investigate variances."]'::jsonb),
('leadership',3,'Leading a kitchen service','Coordinate a safe and consistent service.','["Brief the team on bookings, allergens and responsibilities.","Confirm station readiness and prioritise tasks.","Communicate delays and quality issues clearly.","Debrief after service and agree measurable improvements."]'::jsonb)), added as (insert into public.lessons(title,category,description,steps,status) select title,'Level '||level,description,steps,'published' from seed returning id,title), listed as (insert into public.academy_catalogue(lesson_id) select id from added returning lesson_id) insert into public.academy_module_lessons(module_slug,lesson_id,position) select s.module_slug,a.id,coalesce((select max(position) from public.academy_module_lessons where module_slug=s.module_slug),0)+1 from seed s join added a on a.title=s.title join listed l on l.lesson_id=a.id;
